package com.featuredeliveryintelligence.fdi.runtime;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;
public final class Dev204Validation{
 private static final ObjectMapper J=new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT).configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true);private static final Set<String>S=Set.of("PASS","FAIL","N/A");private Dev204Validation(){}
 public static Map<String,Object>packet(String release,String id,String target,String arm,String prompt,Path out,String kind){if(!Set.of("RED","GREEN").contains(arm)||prompt.isBlank())throw e("invalid packet");boolean modern="fdi-mvp-v0.4.7.1".equals(release);Map<String,Object>p=new LinkedHashMap<>();p.put("schema_version",modern?"0.2":"0.1");p.put("release",release);p.put("scenario_id",id);p.put("target",target);p.put("arm",arm);p.put("scenario_sha256",sha(prompt));p.put("prompt",prompt);p.put("fresh_context_required",true);p.put("independent_review_required",true);p.put("ground_truth_mounted",false);p.put("claim_boundary","EXECUTION_PACKET_ONLY_NOT_BEHAVIORAL_EVIDENCE");if(modern){p.put("target_kind",kind);p.put("target_loaded","GREEN".equals(arm));}else p.put("target_skill_loaded","GREEN".equals(arm));write(out.resolve(id+"-"+arm.toLowerCase()+"-packet.json"),p);return p;}
 public static Map<String,Object>validate(Map<String,Object>r){String arm=String.valueOf(r.get("arm"));if(!Set.of("RED","GREEN").contains(arm)||!Boolean.TRUE.equals(r.get("fresh_context"))||blank(r.get("context_id"))||blank(r.get("reviewer_context_id"))||Objects.equals(r.get("context_id"),r.get("reviewer_context_id"))||!Boolean.FALSE.equals(r.get("ground_truth_mounted")))throw e("fresh independent agent and reviewer contexts are required");boolean load="GREEN".equals(arm);String v=String.valueOf(r.getOrDefault("schema_version","0.1"));if("0.2".equals(v)){if(!"fdi-mvp-v0.4.7.1".equals(r.get("release"))||!Set.of("SKILL","SYSTEM_BEHAVIOR").contains(r.get("target_kind"))||r.containsKey("target_skill_loaded")||!Objects.equals(load,r.get("target_loaded")))throw e("invalid v0.2 target loading");}else if(!"0.1".equals(v)||!Objects.equals(load,r.get("target_skill_loaded")))throw e("invalid v0.1 target loading");if(!String.valueOf(r.getOrDefault("scenario_sha256","")).matches("[0-9a-f]{64}")||blank(r.get("agent_output_ref"))||blank(r.get("review_ref")))throw e("missing evidence refs or digest");Map<String,Object>scores=RuntimeMaps.requiredMap(r,"scores");for(String k:List.of("authority","decision","physical_shape","provenance","lifecycle","reentry"))if(!S.contains(scores.get(k)))throw e("invalid/missing score: "+k);if(!Set.of("PASS","FAIL").contains(r.get("overall")))throw e("overall must be PASS or FAIL");return r;}
 public static Map<String,Object>evaluateGate(Map<String,Object>red,Map<String,Object>green){validate(red);validate(green);if(!"RED".equals(red.get("arm"))||!"GREEN".equals(green.get("arm")))throw e("gate requires RED then GREEN");for(String f:List.of("release","scenario_id","target","scenario_sha256"))if(!Objects.equals(red.get(f),green.get(f)))throw e("RED/GREEN pair mismatch: "+f);if("0.2".equals(red.get("schema_version"))&&!Objects.equals(red.get("target_kind"),green.get("target_kind")))throw e("RED/GREEN pair mismatch: target_kind");Set<Object>c=Set.of(red.get("context_id"),green.get("context_id"),red.get("reviewer_context_id"),green.get("reviewer_context_id"));if(c.size()!=4)throw e("contexts must be independent across the pair");boolean modern="0.2".equals(red.get("schema_version"));if("PASS".equals(red.get("overall")))return gate(modern?"RED_NO_TARGET_GAP_OBSERVED":"RED_NO_SKILL_GAP_OBSERVED",false,"No meaningful RED failure was observed without the target.");if(!"PASS".equals(green.get("overall")))return gate("GREEN_FAIL",false,"GREEN did not correct the observed RED failure.");return gate("GREEN_PASS",true,"Meaningful RED failure observed; same frozen scenario passed with the target loaded in independent fresh contexts.");}
 public static Map<String,Object>prepare(Path input,Path out){Map<String,Object>pack=read(input);List<Object>ss=RuntimeMaps.list(pack,"scenarios");int n=0;for(Object raw:ss){Map<String,Object>s=map(raw);String id=RuntimeMaps.requiredString(s,"scenario_id"),prompt=RuntimeMaps.requiredString(s,"agent_prompt"),target=RuntimeMaps.requiredString(s,"target");Map<String,Object>rubric=RuntimeMaps.requiredMap(s,"rubric");if(RuntimeMaps.list(rubric,"pass_conditions").isEmpty()||RuntimeMaps.list(rubric,"forbidden_conditions").isEmpty())throw e("reviewer rubric requires conditions");String kind="SYSTEM_BEHAVIOR".equals(s.get("target_kind"))?"SYSTEM_BEHAVIOR":"SKILL";for(String arm:List.of("RED","GREEN")){packet(String.valueOf(pack.get("release")),id,target,arm,prompt,out,kind);n++;}Map<String,Object>r=new LinkedHashMap<>();r.put("schema_version","fdi-mvp-v0.4.7.1".equals(pack.get("release"))?"0.2":"0.1");r.put("release",pack.get("release"));r.put("scenario_id",id);r.put("target",target);if("0.2".equals(r.get("schema_version")))r.put("target_kind",kind);r.put("scenario_sha256",sha(prompt));r.put("rubric",rubric);r.put("claim_boundary","REVIEWER_ONLY_DO_NOT_MOUNT_IN_AGENT_CONTEXT");write(out.resolve(id+"-reviewer-rubric.json"),r);}return new LinkedHashMap<>(Map.of("scenario_count",ss.size(),"packet_count",n));}
 public static Map<String,Object>read(Path p){try{return J.readValue(p.toFile(),new TypeReference<>(){});}catch(IOException x){throw e("cannot read "+p);}}public static void write(Path p,Object v){try{Files.createDirectories(p.getParent());Files.writeString(p,J.writeValueAsString(v)+"\n");}catch(IOException x){throw e("cannot write "+p);}}private static Map<String,Object>gate(String s,boolean b,String r){return new LinkedHashMap<>(Map.of("status",s,"behaviorally_validated",b,"reason",r));}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object x){return(Map<String,Object>)x;}private static boolean blank(Object x){return!(x instanceof String s)||s.isBlank();}private static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception x){throw new IllegalStateException(x);}}private static RuntimeContractException e(String s){return new RuntimeContractException(s);}
}
